public class ThreadStateInspector {
    public static void main(String[] args) throws InterruptedException {
        Object lock = new Object();

        Thread worker = new Thread(() -> {
            synchronized (lock) {
                try {
                    lock.wait();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }, "Worker-Thread");

        System.out.println("State after creation: " + worker.getState()); // NEW
        worker.start();
        System.out.println("State after start(): " + worker.getState()); // RUNNABLE

        Thread.sleep(100); // Give worker time to acquire lock and wait()
        System.out.println("State during wait(): " + worker.getState()); // WAITING

        synchronized (lock) {
            lock.notify();
        }

        worker.join();
        System.out.println("State after completion: " + worker.getState()); // TERMINATED
    }
}
